'use strict';

var SearchSymbol = require( './../lib' );

function searcher() {
	var obj = {};

	if ( SearchSymbol ) {
		// Define custom search behavior:
		obj[ SearchSymbol ] = search;
	}
	return obj;
}

function search( str ) {
	// Return the index of substring 'foo':
	return str.indexOf( 'foo' );
}

var obj = searcher();
var str = 'foobar';
var result = str.search( obj );

console.log( result );
// => 0

str = 'barfoo';
result = str.search( obj );

console.log( result );
